// Shared types used across the application.
use serde::{Deserialize, Serialize};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DiffMode {
    Plane,
    Watch,
    Line,
    Word,
}

impl DiffMode {
    pub fn next(self) -> DiffMode {
        match self {
            DiffMode::Plane => DiffMode::Watch,
            DiffMode::Watch => DiffMode::Line,
            DiffMode::Line => DiffMode::Word,
            DiffMode::Word => DiffMode::Plane,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutputMode {
    Output,
    Stdout,
    Stderr,
}

impl OutputMode {
    pub fn next(self) -> OutputMode {
        match self {
            OutputMode::Output => OutputMode::Stdout,
            OutputMode::Stdout => OutputMode::Stderr,
            OutputMode::Stderr => OutputMode::Output,
        }
    }
}

/// A single command execution result.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, Default)]
pub struct CommandResult {
    pub timestamp: String,
    pub command: String,
    pub status: bool,
    pub output: String,
    pub stdout: String,
    pub stderr: String,
}

impl CommandResult {
    pub fn empty() -> CommandResult {
        CommandResult {
            timestamp: String::new(),
            command: String::new(),
            status: true,
            output: String::new(),
            stdout: String::new(),
            stderr: String::new(),
        }
    }

    /// Compare everything except the timestamp.
    pub fn same_content(&self, other: &CommandResult) -> bool {
        self.command == other.command
            && self.status == other.status
            && self.output == other.output
            && self.stdout == other.stdout
            && self.stderr == other.stderr
    }

    pub fn get_output(&self, mode: OutputMode) -> &str {
        match mode {
            OutputMode::Output => &self.output,
            OutputMode::Stdout => &self.stdout,
            OutputMode::Stderr => &self.stderr,
        }
    }

    pub fn to_json(&self) -> String {
        serde_json::to_string(self).unwrap_or_default()
    }
}

pub fn now_timestamp() -> String {
    chrono::Local::now()
        .format("%Y-%m-%d %H:%M:%S%.3f")
        .to_string()
}
