// Minimal POSIX-like shell word splitting.

#[derive(Debug)]
pub struct ParseError;

pub fn split(s: &str) -> Result<Vec<String>, ParseError> {
    #[derive(Clone, Copy)]
    enum St {
        Delim,
        Backslash,
        Unquoted,
        UnquotedBackslash,
        Single,
        Double,
        DoubleBackslash,
        Comment,
    }
    let mut words: Vec<String> = Vec::new();
    let mut word = String::new();
    let mut chars = s.chars();
    let mut st = St::Delim;
    loop {
        let c = chars.next();
        st = match st {
            St::Delim => match c {
                None => break,
                Some('\'') => St::Single,
                Some('"') => St::Double,
                Some('\\') => St::Backslash,
                Some('\t') | Some(' ') | Some('\n') => St::Delim,
                Some('#') => St::Comment,
                Some(ch) => {
                    word.push(ch);
                    St::Unquoted
                }
            },
            St::Backslash => match c {
                None => {
                    word.push('\\');
                    words.push(std::mem::take(&mut word));
                    break;
                }
                Some('\n') => St::Delim,
                Some(ch) => {
                    word.push(ch);
                    St::Unquoted
                }
            },
            St::Unquoted => match c {
                None => {
                    words.push(std::mem::take(&mut word));
                    break;
                }
                Some('\'') => St::Single,
                Some('"') => St::Double,
                Some('\\') => St::UnquotedBackslash,
                Some('\t') | Some(' ') | Some('\n') => {
                    words.push(std::mem::take(&mut word));
                    St::Delim
                }
                Some(ch) => {
                    word.push(ch);
                    St::Unquoted
                }
            },
            St::UnquotedBackslash => match c {
                None => {
                    word.push('\\');
                    words.push(std::mem::take(&mut word));
                    break;
                }
                Some('\n') => St::Unquoted,
                Some(ch) => {
                    word.push(ch);
                    St::Unquoted
                }
            },
            St::Single => match c {
                None => return Err(ParseError),
                Some('\'') => St::Unquoted,
                Some(ch) => {
                    word.push(ch);
                    St::Single
                }
            },
            St::Double => match c {
                None => return Err(ParseError),
                Some('"') => St::Unquoted,
                Some('\\') => St::DoubleBackslash,
                Some(ch) => {
                    word.push(ch);
                    St::Double
                }
            },
            St::DoubleBackslash => match c {
                None => return Err(ParseError),
                Some('\n') => St::Double,
                Some(ch @ '$') | Some(ch @ '`') | Some(ch @ '"') | Some(ch @ '\\') => {
                    word.push(ch);
                    St::Double
                }
                Some(ch) => {
                    word.push('\\');
                    word.push(ch);
                    St::Double
                }
            },
            St::Comment => match c {
                None => break,
                Some('\n') => St::Delim,
                Some(_) => St::Comment,
            },
        };
    }
    Ok(words)
}
