cat > src/panicmsg.rs <<'EOF'
// Helpers to emit panic-style messages that mirror the reference behaviour.
use std::sync::atomic::{AtomicBool, Ordering};

static NOTE_PRINTED: AtomicBool = AtomicBool::new(false);

fn thread_id() -> i64 {
    unsafe { libc_gettid() }
}

extern "C" {
    fn syscall(num: i64, ...) -> i64;
}

unsafe fn libc_gettid() -> i64 {
    // SYS_gettid on x86_64 linux
    syscall(186)
}

/// Print a panic message in the same format as the Rust runtime, then unwind
/// the current thread without invoking the panic hook.
pub fn fake_panic(location: &str, msg: &str) -> ! {
    let name = std::thread::current()
        .name()
        .map(|s| s.to_string())
        .unwrap_or_else(|| "<unnamed>".to_string());
    let mut s = format!(
        "\nthread '{}' ({}) panicked at {}:\n{}\n",
        name,
        thread_id(),
        location,
        msg
    );
    if !NOTE_PRINTED.swap(true, Ordering::SeqCst) {
        s.push_str("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n");
    }
    use std::io::Write;
    let _ = std::io::stderr().write_all(s.as_bytes());
    std::panic::resume_unwind(Box::new(()));
}

/// install a hook that marks the backtrace note as printed.
pub fn install_hook() {
    let default = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let already = NOTE_PRINTED.swap(true, Ordering::SeqCst);
        if already {
            // print without the note
            let name = std::thread::current()
                .name()
                .map(|s| s.to_string())
                .unwrap_or_else(|| "<unnamed>".to_string());
            let loc = info
                .location()
                .map(|l| format!("{}:{}:{}", l.file(), l.line(), l.column()))
                .unwrap_or_default();
            let msg = if let Some(s) = info.payload().downcast_ref::<&str>() {
                s.to_string()
            } else if let Some(s) = info.payload().downcast_ref::<String>() {
                s.clone()
            } else {
                "Box<dyn Any>".to_string()
            };
            eprintln!(
                "\nthread '{}' ({}) panicked at {}:\n{}",
                name,
                thread_id(),
                loc,
                msg
            );
        } else {
            default(info);
        }
    }));
}
EOF"}

