// Command execution.
use crate::common::{now_timestamp, CommandResult};
use crate::panicmsg::fake_panic;
use crate::shellwords;
use std::io::Read;
use std::process::{Command, Stdio};
use std::thread;

#[derive(Clone, Debug)]
pub struct ExecConfig {
    pub shell_command: String,
    pub is_exec: bool,
    pub command: String,
}

fn build_argv(cfg: &ExecConfig) -> Vec<String> {
    if cfg.is_exec {
        let words = match shellwords::split(&cfg.command) {
            Ok(w) => w,
            Err(e) => fake_panic(
                "src/exec.rs:337:54",
                &format!("shell command parse error.: {:?}", e),
            ),
        };
        if words.is_empty() {
            fake_panic(
                "src/exec.rs:203:55",
                "index out of bounds: the len is 0 but the index is 0",
            );
        }
        words
    } else {
        let words = match shellwords::split(&cfg.shell_command) {
            Ok(w) => w,
            Err(e) => fake_panic(
                "src/exec.rs:342:48",
                &format!("shell command parse error.: {:?}", e),
            ),
        };
        if words.is_empty() {
            fake_panic(
                "src/exec.rs:345:42",
                "index out of bounds: the len is 0 but the index is 0",
            );
        }
        let mut argv: Vec<String> = Vec::new();
        argv.push(words[0].clone());
        let has_placeholder = words.iter().any(|w| w.contains("{COMMAND}"));
        for w in &words[1..] {
            if has_placeholder {
                argv.push(w.replace("{COMMAND}", &cfg.command));
            } else {
                argv.push(w.clone());
            }
        }
        if !has_placeholder {
            argv.push(cfg.command.clone());
        } else if words[0].contains("{COMMAND}") {
            argv[0] = words[0].replace("{COMMAND}", &cfg.command);
        }
        argv
    }
}

pub fn exec_command(cfg: &ExecConfig) -> CommandResult {
    let argv = build_argv(cfg);
    let mut cmd = Command::new(&argv[0]);
    cmd.args(&argv[1..])
        .stdin(Stdio::inherit())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    match cmd.spawn() {
        Err(e) => {
            let msg = e.to_string();
            CommandResult {
                timestamp: now_timestamp(),
                command: cfg.command.clone(),
                status: false,
                output: msg.clone(),
                stdout: String::new(),
                stderr: msg,
            }
        }
        Ok(mut child) => {
            let mut out_pipe = child.stdout.take();
            let mut err_pipe = child.stderr.take();
            let out_handle = thread::spawn(move || {
                let mut buf = Vec::new();
                if let Some(p) = out_pipe.as_mut() {
                    let _ = p.read_to_end(&mut buf);
                }
                buf
            });
            let err_handle = thread::spawn(move || {
                let mut buf = Vec::new();
                if let Some(p) = err_pipe.as_mut() {
                    let _ = p.read_to_end(&mut buf);
                }
                buf
            });
            let out_buf = out_handle.join().unwrap_or_default();
            let err_buf = err_handle.join().unwrap_or_default();
            let status = match child.wait() {
                Ok(s) => s.success(),
                Err(_) => false,
            };
            let stdout = String::from_utf8_lossy(&out_buf).to_string();
            let stderr = String::from_utf8_lossy(&err_buf).to_string();
            let mut output = String::with_capacity(stdout.len() + stderr.len());
            output.push_str(&stderr);
            output.push_str(&stdout);
            CommandResult {
                timestamp: now_timestamp(),
                command: cfg.command.clone(),
                status,
                output,
                stdout,
                stderr,
            }
        }
    }
}

/// Run the after command asynchronously with HWATCH_DATA set.
pub fn exec_after_command(after_command: &str, before: &CommandResult, after: &CommandResult) {
    #[derive(serde::Serialize)]
    struct Data<'a> {
        before_result: &'a CommandResult,
        after_result: &'a CommandResult,
    }
    let data = serde_json::to_string(&Data {
        before_result: before,
        after_result: after,
    })
    .unwrap_or_default();
    let ac = after_command.to_string();
    thread::spawn(move || {
        let child = Command::new("sh")
            .arg("-c")
            .arg(&ac)
            .env("HWATCH_DATA", data)
            .stdin(Stdio::null())
            .spawn();
        if let Ok(mut c) = child {
            let _ = c.wait();
        }
    });
}
EOF"}

