        old_index: usize,
        new_index: usize,
        new_len: usize,
    },
    Replace {
        old_index: usize,
        old_len: usize,
        new_index: usize,
        new_len: usize,
    },
}

impl DiffOp {
    pub fn tag(&self) -> DiffTag {
        match self {
            DiffOp::Equal { .. } => DiffTag::Equal,
            DiffOp::Delete { .. } => DiffTag::Delete,
            DiffOp::Insert { .. } => DiffTag::Insert,
            DiffOp::Replace { .. } => DiffTag::Replace,
        }
    }

    pub fn old_range(&self) -> Range<usize> {
        match *self {
            DiffOp::Equal { old_index, len, .. } => old_index..old_index + len,
            DiffOp::Delete {
                old_index, old_len, ..
            } => old_index..old_index + old_len,
            DiffOp::Insert { old_index, .. } => old_index..old_index,
            DiffOp::Replace {
                old_index, old_len, ..
            } => old_index..old_index + old_len,
        }
    }

    pub fn new_range(&self) -> Range<usize> {
        match *self {
            DiffOp::Equal { new_index, len, .. } => new_index..new_index + len,
            DiffOp::Delete { new_index, .. } => new_index..new_index,
            DiffOp::Insert {
                new_index, new_len, ..
            } => new_index..new_index + new_len,
            DiffOp::Replace {
                new_index, new_len, ..
            } => new_index..new_index + new_len,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.old_range().is_empty() && self.new_range().is_empty()
    }

    fn adjust(&mut self, off: (usize, bool), len_adj: (usize, bool)) {
        fn m(v: &mut usize, a: (usize, bool)) {
            if a.1 {
                *v -= a.0;
            } else {
                *v += a.0;
            }
        }
        match self {
            DiffOp::Equal {
                old_index,
                new_index,
                len,
            } => {
                m(old_index, off);
                m(new_index, off);
                m(len, len_adj);
            }
            DiffOp::Delete {
                old_index,
                old_len,
                new_index,
            } => {
                m(old_index, off);
                m(old_len, len_adj);
                m(new_index, off);
            }
            DiffOp::Insert {
                old_index,
                new_index,
                new_len,
            } => {
                m(old_index, off);
                m(new_index, off);
                m(new_len, len_adj);
            }
            DiffOp::Replace {
                old_index,
                old_len,
                new_index,
                new_len,
            } => {
                m(old_index, off);
                m(old_len, len_adj);
                m(new_index, off);
                m(new_len, len_adj);
            }
        }
    }

    pub fn shift_left(&mut self, n: usize) {
        self.adjust((n, true), (0, false));
    }
    pub fn shift_right(&mut self, n: usize) {
        self.adjust((n, false), (0, false));
    }
    pub fn grow_left(&mut self, n: usize) {
        self.adjust((n, true), (n, false));
    }
    pub fn grow_right(&mut self, n: usize) {
        self.adjust((0, false), (n, false));
    }
    pub fn shrink_left(&mut self, n: usize) {
        self.adjust((0, false), (n, true));
    }
    pub fn shrink_right(&mut self, n: usize) {
        self.adjust((n, false), (n, true));
    }
}

/// Receiver of diff events.
pub trait DiffHook {
    fn equal(&mut self, _old_index: usize, _new_index: usize, _len: usize) {}
    fn delete(&mut self, _old_index: usize, _old_len: usize, _new_index: usize) {}
    fn insert(&mut self, _old_index: usize, _new_index: usize, _new_len: usize) {}
    fn replace(&mut self, old_index: usize, old_len: usize, new_index: usize, new_len: usize) {
        self.delete(old_index, old_len, new_index);
        self.insert(old_index, new_index, new_len);
    }
    fn finish(&mut self) {}
}

impl<D: DiffHook + ?Sized> DiffHook for &mut D {
    fn equal(&mut self, a: usize, b: usize, c: usize) {
        (**self).equal(a, b, c)
    }
    fn delete(&mut self, a: usize, b: usize, c: usize) {
        (**self).delete(a, b, c)
    }
    fn insert(&mut self, a: usize, b: usize, c: usize) {
        (**self).insert(a, b, c)
    }
    fn replace(&mut self, a: usize, b: usize, c: usize, d: usize) {
        (**self).replace(a, b, c, d)
    }
    fn finish(&mut self) {
        (**self).finish()
    }
}

/// Wrapper that swallows `finish`.
pub struct NoFinish<'a, D: DiffHook>(pub &'a mut D);

impl<'a, D: DiffHook> DiffHook for NoFinish<'a, D> {
    fn equal(&mut self, a: usize, b: usize, c: usize) {
        self.0.equal(a, b, c)
    }
    fn delete(&mut self, a: usize, b: usize, c: usize) {
        self.0.delete(a, b, c)
    }
    fn insert(&mut self, a: usize, b: usize, c: usize) {
        self.0.insert(a, b, c)
    }
    fn replace(&mut self, a: usize, b: usize, c: usize, d: usize) {
        self.0.replace(a, b, c, d)
    }
    fn finish(&mut self) {}
}

/// Collects operations.
#[derive(Default)]
pub struct Capture {
    pub ops: Vec<DiffOp>,
}

impl DiffHook for Capture {
    fn equal(&mut self, old_index: usize, new_index: usize, len: usize) {
        self.ops.push(DiffOp::Equal {
            old_index,
            new_index,
            len,
        });
    }
    fn delete(&mut self, old_index: usize, old_len: usize, new_index: usize) {
        self.ops.push(DiffOp::Delete {
            old_index,
            old_len,
            new_index,
        });
    }
    fn insert(&mut self, old_index: usize, new_index: usize, new_len: usize) {
        self.ops.push(DiffOp::Insert {
            old_index,
            new_index,
            new_len,
        });
    }
    fn replace(&mut self, old_index: usize, old_len: usize, new_index: usize, new_len: usize) {
        self.ops.push(DiffOp::Replace {
            old_index,
            old_len,
            new_index,
            new_len,
        });
    }
}

/// Merges adjacent delete/insert runs into replace operations.
pub struct Replace<D: DiffHook> {
    pub d: D,
    del: Option<(usize, usize, usize)>,
    ins: Option<(usize, usize, usize)>,
    eq: Option<(usize, usize, usize)>,
}

impl<D: DiffHook> Replace<D> {
    pub fn new(d: D) -> Self {
        Replace {
            d,
            del: None,
            ins: None,
            eq: None,
        }
    }

    fn flush_eq(&mut self) {
        if let Some((a, b, c)) = self.eq.take() {
            self.d.equal(a, b, c);
        }
    }

    fn flush_del_ins(&mut self) {
        if let Some((del_old_index, del_old_len, del_new_index)) = self.del.take() {
            if let Some((_, ins_new_index, ins_new_len)) = self.ins.take() {
                self.d
                    .replace(del_old_index, del_old_len, ins_new_index, ins_new_len);
            } else {
                self.d.delete(del_old_index, del_old_len, del_new_index);
            }
        } else if let Some((ins_old_index, ins_new_index, ins_new_len)) = self.ins.take() {
            self.d.insert(ins_old_index, ins_new_index, ins_new_len);
        }
    }
}

impl<D: DiffHook> DiffHook for Replace<D> {
    fn equal(&mut self, old_index: usize, new_index: usize, len: usize) {
        self.flush_del_ins();
        self.eq = if let Some((a, b, l)) = self.eq.take() {
            Some((a, b, l + len))
        } else {
            Some((old_index, new_index, len))
        };
    }
    fn delete(&mut self, old_index: usize, old_len: usize, new_index: usize) {
        self.flush_eq();
        if let Some((a, l, b)) = self.del.take() {
            self.del = Some((a, l + old_len, b));
        } else {
            self.del = Some((old_index, old_len, new_index));
        }
    }
    fn insert(&mut self, old_index: usize, new_index: usize, new_len: usize) {
        self.flush_eq();
        self.ins = if let Some((a, b, l)) = self.ins.take() {
            Some((a, b, new_len + l))
        } else {
            Some((old_index, new_index, new_len))
        };
    }
    fn replace(&mut self, old_index: usize, old_len: usize, new_index: usize, new_len: usize) {
        self.flush_eq();
        self.d.replace(old_index, old_len, new_index, new_len);
    }
    fn finish(&mut self) {
        self.flush_eq();
        self.flush_del_ins();
        self.d.finish();
    }
}

pub fn common_prefix_len<T: PartialEq>(
    old: &[T],
    old_range: Range<usize>,
    new: &[T],
    new_range: Range<usize>,
) -> usize {
    if old_range.is_empty() || new_range.is_empty() {
        return 0;
    }
    new_range
        .zip(old_range)
        .take_while(|x| new[x.0] == old[x.1])
        .count()
}

pub fn common_suffix_len<T: PartialEq>(
    old: &[T],
    old_range: Range<usize>,
    new: &[T],
    new_range: Range<usize>,
) -> usize {
    if old_range.is_empty() || new_range.is_empty() {
        return 0;
    }
    new_range
        .rev()
        .zip(old_range.rev())
        .take_while(|x| new[x.0] == old[x.1])
        .count()
}
