// Patience diff algorithm.
use super::myers;
use super::ops::{DiffHook, NoFinish, Replace};
use std::collections::HashMap;
use std::hash::Hash;
use std::ops::Range;

#[derive(Clone, Copy)]
struct UniqueItem<'a, T> {
    lookup: &'a [T],
    index: usize,
}

impl<'a, T: PartialEq> PartialEq for UniqueItem<'a, T> {
    fn eq(&self, other: &Self) -> bool {
        self.lookup[self.index] == other.lookup[other.index]
    }
}

fn unique<T: Hash + Eq>(lookup: &[T], range: Range<usize>) -> Vec<UniqueItem<'_, T>> {
    let mut by_item: HashMap<&T, Option<usize>> = HashMap::new();
    for index in range {
        match by_item.get_mut(&lookup[index]) {
            None => {
                by_item.insert(&lookup[index], Some(index));
            }
            Some(e) => {
                if e.is_some() {
                    *e = None;
                }
            }
        }
    }
    let mut rv: Vec<UniqueItem<T>> = by_item
        .into_iter()
        .filter_map(|(_, x)| x)
        .map(|index| UniqueItem { lookup, index })
        .collect();
    rv.sort_by_key(|a| a.index);
    rv
}

struct Patience<'a, T, D: DiffHook> {
    d: &'a mut D,
    old: &'a [T],
    old_current: usize,
    old_end: usize,
    old_indexes: &'a [UniqueItem<'a, T>],
    new: &'a [T],
    new_current: usize,
    new_end: usize,
    new_indexes: &'a [UniqueItem<'a, T>],
}

impl<'a, T: PartialEq, D: DiffHook> DiffHook for Patience<'a, T, D> {
    fn equal(&mut self, old: usize, new: usize, len: usize) {
        for (old, new) in (old..old + len).zip(new..new + len) {
            let a0 = self.old_current;
            let b0 = self.new_current;
            while self.old_current < self.old_indexes[old].index
                && self.new_current < self.new_indexes[new].index
                && self.new[self.new_current] == self.old[self.old_current]
            {
                self.old_current += 1;
                self.new_current += 1;
            }
            if self.old_current > a0 {
                self.d.equal(a0, b0, self.old_current - a0);
            }
            let mut nf = NoFinish(&mut *self.d);
            myers::diff(
                &mut nf,
                self.old,
                self.old_current..self.old_indexes[old].index,
                self.new,
                self.new_current..self.new_indexes[new].index,
            );
            self.old_current = self.old_indexes[old].index;
            self.new_current = self.new_indexes[new].index;
        }
    }

    fn finish(&mut self) {
        myers::diff(
            &mut *self.d,
            self.old,
            self.old_current..self.old_end,
            self.new,
            self.new_current..self.new_end,
        );
    }
}

pub fn diff<T: Hash + Eq, D: DiffHook>(
    d: &mut D,
    old: &[T],
    old_range: Range<usize>,
    new: &[T],
    new_range: Range<usize>,
) {
    let old_indexes = unique(old, old_range.clone());
    let new_indexes = unique(new, new_range.clone());
    let p = Patience {
        d,
        old,
        old_current: old_range.start,
        old_end: old_range.end,
        old_indexes: &old_indexes,
        new,
        new_current: new_range.start,
        new_end: new_range.end,
        new_indexes: &new_indexes,
    };
    let mut r = Replace::new(p);
    myers::diff(
        &mut r,
        &old_indexes,
        0..old_indexes.len(),
        &new_indexes,
        0..new_indexes.len(),
    );
}
