// Semantic cleanup of diff operations: shift hunks to merge them.
use super::ops::{common_prefix_len, common_suffix_len, DiffHook, DiffOp, DiffTag};

pub struct Compact<'a, T, D: DiffHook> {
    pub d: D,
    ops: Vec<DiffOp>,
    old: &'a [T],
    new: &'a [T],
}

impl<'a, T: PartialEq, D: DiffHook> Compact<'a, T, D> {
    pub fn new(d: D, old: &'a [T], new: &'a [T]) -> Self {
        Compact {
            d,
            ops: Vec::new(),
            old,
            new,
        }
    }
}

fn apply<D: DiffHook>(op: &DiffOp, d: &mut D) {
    match *op {
        DiffOp::Equal {
            old_index,
            new_index,
            len,
        } => d.equal(old_index, new_index, len),
        DiffOp::Delete {
            old_index,
            old_len,
            new_index,
        } => d.delete(old_index, old_len, new_index),
        DiffOp::Insert {
            old_index,
            new_index,
            new_len,
        } => d.insert(old_index, new_index, new_len),
        DiffOp::Replace {
            old_index,
            old_len,
            new_index,
            new_len,
        } => d.replace(old_index, old_len, new_index, new_len),
    }
}

impl<'a, T: PartialEq, D: DiffHook> DiffHook for Compact<'a, T, D> {
    fn equal(&mut self, old_index: usize, new_index: usize, len: usize) {
        self.ops.push(DiffOp::Equal {
            old_index,
            new_index,
            len,
        });
    }
    fn delete(&mut self, old_index: usize, old_len: usize, new_index: usize) {
        self.ops.push(DiffOp::Delete {
            old_index,
            old_len,
            new_index,
        });
    }
    fn insert(&mut self, old_index: usize, new_index: usize, new_len: usize) {
        self.ops.push(DiffOp::Insert {
            old_index,
            new_index,
            new_len,
        });
    }
    fn finish(&mut self) {
        cleanup_diff_ops(self.old, self.new, &mut self.ops);
        for op in &self.ops {
            apply(op, &mut self.d);
        }
        self.d.finish();
    }
}

pub fn cleanup_diff_ops<T: PartialEq>(old: &[T], new: &[T], ops: &mut Vec<DiffOp>) {
    let mut pointer = 0;
    while let Some(&op) = ops.get(pointer) {
        if let DiffTag::Delete = op.tag() {
            pointer = shift_diff_ops_up(ops, old, new, pointer);
            pointer = shift_diff_ops_down(ops, old, new, pointer);
        }
        pointer += 1;
    }
    let mut pointer = 0;
    while let Some(&op) = ops.get(pointer) {
        if let DiffTag::Insert = op.tag() {
            pointer = shift_diff_ops_up(ops, old, new, pointer);
            pointer = shift_diff_ops_down(ops, old, new, pointer);
        }
        pointer += 1;
    }
}

