// Text diffing (line based with inline word emphasis).
pub mod compact;
pub mod myers;
pub mod ops;
pub mod patience;

use compact::Compact;
use ops::{Capture, DiffOp, Replace};
use std::hash::Hash;
use unicode_segmentation::UnicodeSegmentation;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ChangeTag {
    Equal,
    Delete,
    Insert,
}

/// Run the given algorithm and return compacted / replaced ops.
pub fn capture_diff<T: Hash + Eq>(old: &[T], new: &[T], patience_alg: bool) -> Vec<DiffOp> {
    let mut c = Compact::new(Replace::new(Capture::default()), old, new);
    if patience_alg {
        patience::diff(&mut c, old, 0..old.len(), new, 0..new.len());
    } else {
        myers::diff(&mut c, old, 0..old.len(), new, 0..new.len());
    }
    c.d.d.ops
}

/// Split into lines keeping line terminators.
pub fn tokenize_lines(s: &str) -> Vec<&str> {
    let bytes = s.as_bytes();
    let mut lines = Vec::new();
    let mut last = 0;
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'\r' {
            if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                lines.push(&s[last..i + 2]);
                i += 2;
                last = i;
                continue;
            } else {
                lines.push(&s[last..i + 1]);
                last = i + 1;
            }
        } else if c == b'\n' {
            lines.push(&s[last..i + 1]);
            last = i + 1;
        }
        i += 1;
    }
    if last < s.len() {
        lines.push(&s[last..]);
    }
    lines
}

fn tokenize_lines_and_newlines(s: &str) -> Vec<&str> {
    let mut rv = Vec::new();
    let mut iter = s.char_indices().peekable();
    while let Some((idx, c)) = iter.next() {
        let is_nl = c == '\r' || c == '\n';
        let start = idx;
        let mut end = idx + c.len_utf8();
        while let Some(&(_, nc)) = iter.peek() {
            if (nc == '\r' || nc == '\n') != is_nl {
                break;
            }
            iter.next();
            end += nc.len_utf8();
        }
        rv.push(&s[start..end]);
    }
    rv
}

fn ends_with_newline(s: &str) -> bool {
    s.ends_with('\r') || s.ends_with('\n')
}

pub struct TextDiff<'a> {
    pub old: Vec<&'a str>,
    pub new: Vec<&'a str>,
    pub ops: Vec<DiffOp>,
}

/// One rendered change line with emphasis segments.
#[derive(Clone, Debug)]
pub struct InlineChange<'a> {
    pub tag: ChangeTag,
    pub old_index: Option<usize>,
    pub new_index: Option<usize>,
    pub values: Vec<(bool, &'a str)>,
}

impl<'a> TextDiff<'a> {
    pub fn from_lines(old: &'a str, new: &'a str) -> TextDiff<'a> {
        let o = tokenize_lines(old);
        let n = tokenize_lines(new);
        let ops = capture_diff(&o, &n, false);
        TextDiff {
            old: o,
            new: n,
            ops,
        }
    }

    pub fn iter_changes(&self, op: &DiffOp) -> Vec<InlineChange<'a>> {
        let mut rv = Vec::new();
        match *op {
            DiffOp::Equal {
                old_index,
                new_index,
                len,
            } => {
                for i in 0..len {
                    rv.push(InlineChange {
                        tag: ChangeTag::Equal,
                        old_index: Some(old_index + i),
                        new_index: Some(new_index + i),
                        values: vec![(false, self.old[old_index + i])],
                    });
                }
            }
            DiffOp::Delete {
                old_index, old_len, ..
            } => {
                for i in 0..old_len {
                    rv.push(InlineChange {
                        tag: ChangeTag::Delete,
                        old_index: Some(old_index + i),
                        new_index: None,
                        values: vec![(false, self.old[old_index + i])],
                    });
                }
            }
            DiffOp::Insert {
                new_index, new_len, ..
            } => {
                for i in 0..new_len {
                    rv.push(InlineChange {
                        tag: ChangeTag::Insert,
                        old_index: None,
                        new_index: Some(new_index + i),
                        values: vec![(false, self.new[new_index + i])],
                    });
                }
            }
            DiffOp::Replace {
                old_index,
                old_len,
                new_index,
                new_len,
            } => {
                for i in 0..old_len {
                    rv.push(InlineChange {
                        tag: ChangeTag::Delete,
                        old_index: Some(old_index + i),
                        new_index: None,
                        values: vec![(false, self.old[old_index + i])],
                    });
                }
                for i in 0..new_len {
                    rv.push(InlineChange {
                        tag: ChangeTag::Insert,
                        old_index: None,
                        new_index: Some(new_index + i),
                        values: vec![(false, self.new[new_index + i])],
                    });
                }
            }
        }
        rv
    }

    pub fn iter_inline_changes(&self, op: &DiffOp) -> Vec<InlineChange<'a>> {
        let (old_index, old_len, new_index, new_len) = match *op {
            DiffOp::Replace {
                old_index,
                old_len,
                new_index,
                new_len,
            } => (old_index, old_len, new_index, new_len),
            _ => return self.iter_changes(op),
        };
        let old_slices = &self.old[old_index..old_index + old_len];
        let new_slices = &self.new[new_index..new_index + new_len];
        let old_lookup = MultiLookup::new(old_slices);
        let new_lookup = MultiLookup::new(new_slices);
        let old_words: Vec<&str> = old_lookup.seqs.iter().map(|x| x.0).collect();
        let new_words: Vec<&str> = new_lookup.seqs.iter().map(|x| x.0).collect();
        let ops = capture_diff(&old_words, &new_words, true);

        let mut old_values: Vec<Vec<(bool, &'a str)>> = Vec::new();
        let mut new_values: Vec<Vec<(bool, &'a str)>> = Vec::new();

        for op in ops {
            match op {
                DiffOp::Equal {
                    old_index,
                    len,
                    new_index,
                } => {
                    for (idx, slice) in old_lookup.get_original_slices(old_index, len) {
                        push_values(&mut old_values, idx, false, slice);
                    }
                    for (idx, slice) in new_lookup.get_original_slices(new_index, len) {
                        push_values(&mut new_values, idx, false, slice);
                    }
                }
                DiffOp::Delete {
                    old_index, old_len, ..
                } => {
                    for (idx, slice) in old_lookup.get_original_slices(old_index, old_len) {
                        push_values(&mut old_values, idx, true, slice);
                    }
                }
                DiffOp::Insert {
                    new_index, new_len, ..
                } => {
                    for (idx, slice) in new_lookup.get_original_slices(new_index, new_len) {
                        push_values(&mut new_values, idx, true, slice);
                    }
                }
                DiffOp::Replace {
                    old_index,
                    old_len,
                    new_index,
                    new_len,
                } => {
                    for (idx, slice) in old_lookup.get_original_slices(old_index, old_len) {
                        push_values(&mut old_values, idx, true, slice);
                    }
                    for (idx, slice) in new_lookup.get_original_slices(new_index, new_len) {
                        push_values(&mut new_values, idx, true, slice);
                    }
                }
            }
        }

        let mut rv = Vec::new();
        let mut oi = old_index;
        for values in old_values {
            rv.push(InlineChange {
                tag: ChangeTag::Delete,
                old_index: Some(oi),
                new_index: None,
                values,
            });
            oi += 1;
        }
        let mut ni = new_index;
        for values in new_values {
            rv.push(InlineChange {
                tag: ChangeTag::Insert,
                old_index: None,
                new_index: Some(ni),
                values,
            });
            ni += 1;
        }
        rv
    }
}

fn push_values<'a>(v: &mut Vec<Vec<(bool, &'a str)>>, idx: usize, emphasized: bool, s: &'a str) {
    let need = (idx + 1).max(v.len());
    v.resize_with(need, Vec::new);
    if emphasized {
        for seg in tokenize_lines_and_newlines(s) {
            v[idx].push((!ends_with_newline(seg), seg));
        }
    } else {
        v[idx].push((false, s));
    }
}

struct MultiLookup<'a> {
    strings: Vec<&'a str>,
    seqs: Vec<(&'a str, usize, usize)>,
}

impl<'a> MultiLookup<'a> {
    fn new(strings: &[&'a str]) -> MultiLookup<'a> {
        let mut seqs = Vec::new();
        for (string_idx, string) in strings.iter().enumerate() {
            let mut offset = 0;
            for word in string.split_word_bounds() {
                seqs.push((word, string_idx, offset));
                offset += word.len();
            }
        }
        MultiLookup {
            strings: strings.to_vec(),
            seqs,
        }
    }

    fn get_original_slices(&self, idx: usize, len: usize) -> Vec<(usize, &'a str)> {
        let mut last: Option<(usize, usize, usize)> = None;
        let mut rv = Vec::new();
        for offset in 0..len {
            let (s, str_idx, char_idx) = self.seqs[idx + offset];
            last = match last {
                None => Some((str_idx, char_idx, s.len())),
                Some((last_str_idx, start_char_idx, last_len)) => {
                    if last_str_idx == str_idx {
                        Some((str_idx, start_char_idx, last_len + s.len()))
                    } else {
                        rv.push((
                            last_str_idx,
                            &self.strings[last_str_idx][start_char_idx..start_char_idx + last_len],
                        ));
                        Some((str_idx, char_idx, s.len()))
                    }
                }
            };
        }
        if let Some((str_idx, start_char_idx, len)) = last {
            rv.push((
                str_idx,
                &self.strings[str_idx][start_char_idx..start_char_idx + len],
            ));
        }
        rv
    }
}
