// Removal of a fixed set of VT100 escape sequences from text.
// Unrecognised escape sequences are left untouched.

fn digits(s: &[u8], i: usize) -> usize {
    let mut j = i;
    while j < s.len() && s[j].is_ascii_digit() {
        j += 1;
    }
    j
}

fn parse_u8_at(s: &[u8], i: usize) -> Option<usize> {
    let j = digits(s, i);
    if j == i {
        return None;
    }
    let txt = std::str::from_utf8(&s[i..j]).ok()?;
    txt.parse::<u8>().ok()?;
    Some(j)
}

fn parse_u32_at(s: &[u8], i: usize) -> Option<usize> {
    let j = digits(s, i);
    if j == i {
        return None;
    }
    let txt = std::str::from_utf8(&s[i..j]).ok()?;
    txt.parse::<u32>().ok()?;
    Some(j)
}

fn tag(s: &[u8], i: usize, t: &[u8]) -> Option<usize> {
    if s.len() >= i + t.len() && &s[i..i + t.len()] == t {
        Some(i + t.len())
    } else {
        None
    }
}

fn graphics_n(s: &[u8], i: usize, n: usize) -> Option<usize> {
    let mut p = tag(s, i, b"[")?;
    for k in 0..n {
        if k > 0 {
            p = tag(s, p, b";")?;
        }
        p = parse_u8_at(s, p)?;
    }
    tag(s, p, b"m")
}

/// Try to parse a recognised escape sequence. `i` points just after ESC.
/// Returns the index after the sequence.
fn parse_sequence(s: &[u8], i: usize) -> Option<usize> {
    // ESC ESC
    if let Some(p) = tag(s, i, b"\x1b") {
        return Some(p);
    }
    // cursor position: [ digit0 ;? digit0 (H|f)
    if let Some(p) = tag(s, i, b"[") {
        let p1 = digits(s, p);
        let p2 = tag(s, p1, b";").unwrap_or(p1);
        let p3 = digits(s, p2);
        if p3 < s.len() && (s[p3] == b'H' || s[p3] == b'f') {
            return Some(p3 + 1);
        }
    }
    // cursor movement
    for f in [b'A', b'B', b'C', b'D'] {
        if let Some(p) = tag(s, i, b"[") {
            let p1 = digits(s, p);
            if p1 < s.len() && s[p1] == f {
                return Some(p1 + 1);
            }
        }
    }
    for t in [&b"[s"[..], b"[u", b"[2J", b"[K"] {
        if let Some(p) = tag(s, i, t) {
            return Some(p);
        }
    }
    // graphics mode
    for n in [1usize, 2, 3, 5] {
        if let Some(p) = graphics_n(s, i, n) {
            return Some(p);
        }
    }
    if let Some(p) = tag(s, i, b"[m") {
        return Some(p);
    }
    // set / reset mode
    if let Some(p) = tag(s, i, b"[=") {
        if let Some(p1) = parse_u8_at(s, p) {
            if let Some(p2) = tag(s, p1, b"h") {
                return Some(p2);
            }
            if let Some(p2) = tag(s, p1, b"l") {
                return Some(p2);
            }
        }
    }
    let tags: [&[u8]; 21] = [
        b"[?25l", b"[?25h", b"[?1h", b"[20h", b"[?3h", b"[?4h", b"[?5h", b"[?6h", b"[?7h",
        b"[?8h", b"[?9h", b"[20l", b"[?1l", b"[?2l", b"[?3l", b"[?4l", b"[?5l", b"[?6l",
        b"[?7l", b"[?8l", b"[?9l",
    ];
    for t in tags.iter() {
        if let Some(p) = tag(s, i, t) {
            return Some(p);
        }
    }
    // top and bottom
    if let Some(p) = tag(s, i, b"[") {
        if let Some(p1) = parse_u32_at(s, p) {
            if let Some(p2) = tag(s, p1, b";") {
                if let Some(p3) = parse_u32_at(s, p2) {
                    if let Some(p4) = tag(s, p3, b"r") {
                        return Some(p4);
                    }
                }
            }
        }
    }
    let tags2: [&[u8]; 16] = [
        b"=", b">", b"(A", b")A", b"(B", b")B", b"(0", b")0", b"(1", b")1", b"(2", b")2", b"N",
        b"O", b"", b"",
    ];
    for t in tags2.iter() {
        if t.is_empty() {
            continue;
        }
        if let Some(p) = tag(s, i, t) {
            return Some(p);
        }
    }
    None
}

/// Strip recognised escape sequences.
pub fn strip(text: &str) -> String {
    let s = text.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(s.len());
    let mut pos = 0;
    while pos < s.len() {
        // find next ESC
        match s[pos..].iter().position(|&b| b == 0x1b) {
            None => {
                out.extend_from_slice(&s[pos..]);
                break;
            }
            Some(off) => {
                if off > 0 {
                    out.extend_from_slice(&s[pos..pos + off]);
                    pos += off;
                    continue;
                }
                // at ESC
                if let Some(end) = parse_sequence(s, pos + 1) {
                    pos = end;
                } else {
                    // text block up to next ESC
                    match s[pos + 1..].iter().position(|&b| b == 0x1b) {
                        Some(o2) => {
                            out.extend_from_slice(&s[pos..pos + 1 + o2]);
                            pos = pos + 1 + o2;
                        }
                        None => {
                            out.extend_from_slice(&s[pos..]);
                            pos = s.len();
                        }
                    }
                }
            }
        }
    }
    String::from_utf8_lossy(&out).to_string()
}
