// Batch mode: print changes to stdout.
use crate::ansi_strip;
use crate::common::{CommandResult, DiffMode, OutputMode};
use crate::diff::{ChangeTag, TextDiff};
use crate::exec::exec_after_command;
use crate::logger::Logger;
use std::io::Write;
use std::sync::mpsc::Receiver;

pub struct BatchConfig {
    pub diff_mode: DiffMode,
    pub output_mode: OutputMode,
    pub line_number: bool,
    pub reverse: bool,
    pub diff_only: bool,
    pub beep: bool,
    pub after_command: Option<String>,
}

const ZWSP: &str = "\u{200b}";

fn digits(n: usize) -> usize {
    n.to_string().len()
}

fn number_prefix(n: usize, width: usize, color: &str) -> String {
    let s = n.to_string();
    let pad = width.saturating_sub(s.len());
    format!(
        "{}{}{}\x1b[0m{} | \x1b[0m",
        " ".repeat(pad),
        color,
        s,
        color
    )
}

const GRAY: &str = "\x1b[38;5;240m";
const NUM_DEL: &str = "\x1b[38;2;118;0;0m";
const NUM_INS: &str = "\x1b[38;2;56;119;120m";

pub fn watch_diff_line_ansi(old_line: &str, new_line: &str) -> String {
    if old_line == new_line {
        return new_line.to_string();
    }
    let oc: Vec<char> = old_line.chars().collect();
    let nc: Vec<char> = new_line.chars().collect();
    let max = oc.len().max(nc.len());
    let mut s = String::new();
    let mut esc_mode = false;
    let mut esc = String::new();
    for x in 0..max {
        if x >= nc.len() {
            s.push_str("\x1b[7m \x1b[7m");
            continue;
        }
        let c = nc[x];
        if oc.get(x) == Some(&c) {
            s.push(c);
            continue;
        }
        if c == '\x1b' {
            esc_mode = true;
            esc = "\x1b".to_string();
            continue;
        }
        if esc_mode {
            esc.push(c);
            s.push_str(&esc);
            if c == 'm' {
                esc_mode = false;
            }
            continue;
        }
        s.push_str("\x1b[7m");
        s.push(c);
        s.push_str("\x1b[7m");
    }
    s.push_str("\x1b[0m");
    s
}

fn gen_plane(new: &str, line_number: bool) -> Vec<String> {
    let lines: Vec<&str> = new.split('\n').collect();
    let width = digits(lines.len());
    lines
        .iter()
        .enumerate()
        .map(|(i, l)| {
            if line_number {
                format!("{}{}", number_prefix(i + 1, width, GRAY), l)
            } else {
                l.to_string()
            }
        })
        .collect()
}

fn gen_watch(old: &str, new: &str, line_number: bool) -> Vec<String> {
    let ol: Vec<&str> = old.lines().collect();
    let nl: Vec<&str> = new.lines().collect();
    let n = ol.len().max(nl.len());
    let width = digits(n);
    let mut rv = Vec::new();
    for i in 0..n {
        let o = match ol.get(i) {
            Some(l) if l.is_empty() => ZWSP,
            Some(l) => l,
            None => "",
        };
        let nn = match nl.get(i) {
            Some(l) if l.is_empty() => ZWSP,
            Some(l) => l,
            None => "",
        };
        let body = watch_diff_line_ansi(o, nn);
        if line_number {
            rv.push(format!("{}{}", number_prefix(i + 1, width, GRAY), body));
        } else {
            rv.push(body);
        }
    }
    rv
}

fn gen_line_word(old: &str, new: &str, word: bool, line_number: bool, diff_only: bool) -> Vec<String> {
    let old_s = ansi_strip::strip(old);
    let new_s = ansi_strip::strip(new);
    let width = digits(old_s.lines().count().max(new_s.lines().count()));
    let diff = TextDiff::from_lines(&old_s, &new_s);
    let mut rv = Vec::new();
    for op in diff.ops.iter() {
        for change in diff.iter_inline_changes(op) {
            if diff_only && change.tag == ChangeTag::Equal {
                continue;
            }
            let mut line = String::new();
            if line_number {
                let (n, color) = match change.tag {
                    ChangeTag::Equal => (change.old_index.unwrap_or(0) + 1, GRAY),
                    ChangeTag::Delete => (change.old_index.unwrap_or(0) + 1, NUM_DEL),
                    ChangeTag::Insert => (change.new_index.unwrap_or(0) + 1, NUM_INS),
                };
                line.push_str(&number_prefix(n, width, color));
            }
            match change.tag {
                ChangeTag::Equal => line.push_str("   "),
                ChangeTag::Delete => line.push_str("\x1b[31m-  \x1b[0m"),
                ChangeTag::Insert => line.push_str("\x1b[32m+  \x1b[0m"),
            }
            for (emph, value) in change.values.iter() {
                let v = value.replace('\n', "");
                match change.tag {
                    ChangeTag::Equal => line.push_str(&v),
                    ChangeTag::Delete => {
                        if *emph && word {
                            line.push_str(&format!("\x1b[41;37m{}\x1b[0m", v));
                        } else {
                            line.push_str(&format!("\x1b[31m{}\x1b[0m", v));
                        }
                    }
                    ChangeTag::Insert => {
                        if *emph && word {
                            line.push_str(&format!("\x1b[42;37m{}\x1b[0m", v));
                        } else {
                            line.push_str(&format!("\x1b[32m{}\x1b[0m", v));
                        }
                    }
                }
            }
            rv.push(line);
        }
    }
    rv
}

pub fn render(cfg: &BatchConfig, old: &str, new: &str) -> Vec<String> {
    let mut lines = match cfg.diff_mode {
        DiffMode::Plane => gen_plane(new, cfg.line_number),
        DiffMode::Watch => gen_watch(old, new, cfg.line_number),
        DiffMode::Line => gen_line_word(old, new, false, cfg.line_number, cfg.diff_only),
        DiffMode::Word => gen_line_word(old, new, true, cfg.line_number, cfg.diff_only),
    };
    if cfg.reverse {
        lines.reverse();
    }
    lines
}

pub fn run(cfg: BatchConfig, rx: Receiver<CommandResult>, mut logger: Option<Logger>) {
    let mut last = CommandResult::empty();
    let stdout = std::io::stdout();
    while let Ok(result) = rx.recv() {
        if result.same_content(&last) {
            continue;
        }
        let mut text = String::new();
        text.push_str(&format!(
            "\x1b[38;5;240m=====[{}]=========================\x1b[0m\n",
            result.timestamp
        ));
        let lines = render(
            &cfg,
            last.get_output(cfg.output_mode),
            result.get_output(cfg.output_mode),
        );
        for l in lines {
            text.push_str(&l);
            text.push('\n');
        }
        {
            let mut out = stdout.lock();
            if out.write_all(text.as_bytes()).is_err() {
                crate::panicmsg::fake_panic(
                    "library/std/src/io/stdio.rs:1165:9",
                    "failed printing to stdout: Broken pipe (os error 32)",
                );
            }
            if cfg.beep {
                let _ = out.write_all(b"\x07\n");
            }
            let _ = out.flush();
        }
        if let Some(ac) = &cfg.after_command {
            exec_after_command(ac, &last, &result);
        }
        if let Some(l) = logger.as_mut() {
            l.write(&last);
        }
        last = result;
    }
}
EOF"}

