// JSON lines logging.
use crate::common::CommandResult;
use std::fs::OpenOptions;
use std::io::Write;
use std::path::PathBuf;

pub struct Logger {
    path: PathBuf,
}

impl Logger {
    pub fn new(path: PathBuf) -> Logger {
        Logger { path }
    }

    pub fn write(&mut self, result: &CommandResult) {
        if let Ok(mut f) = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
        {
            let mut s = result.to_json();
            s.push('\n');
            let _ = f.write_all(s.as_bytes());
        }
    }
}

#[derive(serde::Deserialize)]
#[allow(dead_code)]
struct CommandResultData {
    timestamp: String,
    command: String,
    status: bool,
    output: String,
    stdout: String,
    stderr: String,
}

pub enum LoadResult {
    Missing,
    Empty,
    Error(String),
    Ok(Vec<CommandResult>),
}

pub fn load(path: &PathBuf) -> LoadResult {
    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(_) => return LoadResult::Missing,
    };
    if data.is_empty() {
        return LoadResult::Empty;
    }
    let text = String::from_utf8_lossy(&data).to_string();
    let stream = serde_json::Deserializer::from_str(&text).into_iter::<CommandResultData>();
    let mut rv = Vec::new();
    for item in stream {
        match item {
            Ok(d) => rv.push(CommandResult {
                timestamp: d.timestamp,
                command: d.command,
                status: d.status,
                output: d.output,
                stdout: d.stdout,
                stderr: d.stderr,
            }),
            Err(e) => return LoadResult::Error(format!("{:?}", e)),
        }
    }
    LoadResult::Ok(rv)
}
EOF"}

