{"command":"cd /workspace; cat > src/main.rs <<'EOF'
mod ansi_strip;
mod batch;
mod cli;
mod common;
mod diff;
mod exec;
mod logger;
mod panicmsg;
mod shellwords;

use common::{CommandResult, DiffMode, OutputMode};
use std::ffi::OsString;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::mpsc;
use std::time::{Duration, Instant};

fn clap_error_exit(msg: &str) -> ! {
    let mut cmd = cli::build_cli();
    let err = cmd.error(clap::error::ErrorKind::InvalidValue, msg);
    err.exit();
}

fn collect_args() -> Vec<OsString> {
    let mut args: Vec<OsString> = std::env::args_os().collect();
    if let Ok(env) = std::env::var("HWATCH") {
        let extra: Vec<OsString> = env.split_whitespace().map(OsString::from).collect();
        if !extra.is_empty() {
            let rest = args.split_off(1);
            args.extend(extra);
            args.extend(rest);
        }
    }
    args
}

fn prompt_same_file() {
    loop {
        print!("Log to the same file? (Y/n) ");
        let _ = std::io::stdout().flush();
        let mut line = String::new();
        let _ = std::io::stdin().read_line(&mut line);
        let ans = line.trim().to_lowercase();
        match ans.as_str() {
            "" | "y" | "yes" => return,
            "n" | "no" => std::process::exit(1),
            _ => continue,
        }
    }
}

fn main() {
    panicmsg::install_hook();
    let args = collect_args();
    let matches = cli::build_cli().get_matches_from(args);

    // logfile handling
    let mut loaded: Vec<CommandResult> = Vec::new();
    let mut logfile: Option<PathBuf> = None;
    if let Some(lf) = matches.get_one::<String>("logfile") {
        let path = PathBuf::from(lf);
        let parent = match Path::new(lf).parent() {
            Some(p) => p.to_path_buf(),
            None => panicmsg::fake_panic(
                "src/main.rs:460:41",
                "called `Option::unwrap()` on a `None` value",
            ),
        };
        let abs_parent = if parent.is_absolute() {
            parent.clone()
        } else {
            std::env::current_dir().unwrap_or_default().join(&parent)
        };
        if !abs_parent.exists() {
            clap_error_exit(&format!("directory {:?} is not exists.", abs_parent));
        }
        match logger::load(&path) {
            logger::LoadResult::Missing => {}
            logger::LoadResult::Empty => {
                eprintln!("file {:?} is exists and empty.", path);
                prompt_same_file();
            }
            logger::LoadResult::Error(e) => {
                eprintln!("file {:?} is exists and json parse error.", path);
                eprintln!("{}", e);
                prompt_same_file();
            }
            logger::LoadResult::Ok(v) => {
                loaded = v;
            }
        }
        logfile = Some(path);
    }

    let output_mode = match matches.get_one::<String>("output") {
        Some(s) => match s.as_str() {
            "stdout" => OutputMode::Stdout,
            "stderr" => OutputMode::Stderr,
            _ => OutputMode::Output,
        },
        None => panicmsg::fake_panic(
            "src/main.rs:537:65",
            "called `Option::unwrap()` on a `None` value",
        ),
    };

    let keymap_args: Vec<String> = matches
        .get_many::<String>("keymap")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let _ = keymap_args;

    let command_parts: Vec<String> = matches
        .get_many::<String>("command")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let command = if !command_parts.is_empty() {
        command_parts.join(" ")
    } else if let Some(last) = loaded.last() {
        last.command.clone()
    } else {
        clap_error_exit("command not specified and logfile is empty.");
    };

    let diff_mode = match matches.get_one::<String>("differences").map(|s| s.as_str()) {
        Some("watch") => DiffMode::Watch,
        Some("line") => DiffMode::Line,
        Some("word") => DiffMode::Word,
        _ => DiffMode::Plane,
    };
    let interval = *matches.get_one::<f64>("interval").unwrap();
    let batch = matches.get_flag("batch");
    let shell_command = matches.get_one::<String>("shell_command").unwrap().clone();

    let exec_cfg = exec::ExecConfig {
        shell_command,
        is_exec: matches.get_flag("exec"),
        command: command.clone(),
    };
    let precise = matches.get_flag("precise");

    if batch {
        let (tx, rx) = mpsc::channel::<CommandResult>();
        let cfg = exec_cfg.clone();
        std::thread::spawn(move || {
            run_loop(cfg, interval, precise, tx);
        });
        let bcfg = batch::BatchConfig {
            diff_mode,
            output_mode,
