        _ => "unknown".into(),
    }
}

impl Input {
    pub fn display(&self) -> String {
        match self {
            Input::Mouse(k) => format!("mouse-{}", k.name()),
            Input::Key(code, mods) => {
                let mut s = String::new();
                if mods.contains(KeyModifiers::SHIFT) {
                    s.push_str("shift-");
                }
                if mods.contains(KeyModifiers::CONTROL) {
                    s.push_str("ctrl-");
                }
                if mods.contains(KeyModifiers::ALT) {
                    s.push_str("alt-");
                }
                if mods.contains(KeyModifiers::SUPER) {
                    s.push_str("super-");
                }
                if mods.contains(KeyModifiers::HYPER) {
                    s.push_str("hyper-");
                }
                if mods.contains(KeyModifiers::META) {
                    s.push_str("meta-");
                }
                s.push_str(&code_name(code));
                s
            }
        }
    }
}

fn parse_code(s: &str) -> Option<KeyCode> {
    Some(match s {
        "esc" => KeyCode::Esc,
        "tab" => KeyCode::Tab,
        "backtab" => KeyCode::BackTab,
        "backspace" => KeyCode::Backspace,
        "enter" => KeyCode::Enter,
        "space" => KeyCode::Char(' '),
        "up" => KeyCode::Up,
        "down" => KeyCode::Down,
        "left" => KeyCode::Left,
        "right" => KeyCode::Right,
        "home" => KeyCode::Home,
        "end" => KeyCode::End,
        "pageup" => KeyCode::PageUp,
        "pagedown" => KeyCode::PageDown,
        "insert" | "ins" => KeyCode::Insert,
        "delete" | "del" => KeyCode::Delete,
        "f1" => KeyCode::F(1),
        "f2" => KeyCode::F(2),
        "f3" => KeyCode::F(3),
        "f4" => KeyCode::F(4),
        "f5" => KeyCode::F(5),
        "f6" => KeyCode::F(6),
        "f7" => KeyCode::F(7),
        "f8" => KeyCode::F(8),
        "f9" => KeyCode::F(9),
        "f10" => KeyCode::F(10),
        "f11" => KeyCode::F(11),
        "f12" => KeyCode::F(12),
        _ => {
            if s.len() == 1 {
                KeyCode::Char(s.chars().next().unwrap())
            } else {
                return None;
            }
        }
    })
}

pub fn parse_input(s: &str) -> Option<Input> {
    let s = s.trim().to_lowercase();
    if let Some(rest) = s.strip_prefix("mouse-") {
        return MouseKind::from_name(rest).map(Input::Mouse);
    }
    let parts: Vec<&str> = s.split('-').collect();
    let last = *parts.last()?;
    if last.is_empty() {
        return None;
    }
    let code = parse_code(last)?;
    let mut mods = KeyModifiers::NONE;
    for p in &parts[..parts.len() - 1] {
        match *p {
            "shift" => mods |= KeyModifiers::SHIFT,
            "ctrl" => mods |= KeyModifiers::CONTROL,
            "alt" => mods |= KeyModifiers::ALT,
            "super" => mods |= KeyModifiers::SUPER,
            "hyper" => mods |= KeyModifiers::HYPER,
            "meta" => mods |= KeyModifiers::META,
            _ => {}
        }
    }
    Some(Input::Key(code, mods))
}

/// Convert a key event into the canonical input.
pub fn input_from_key(ev: &KeyEvent) -> Input {
    let mut mods = ev.modifiers;
    let code = match ev.code {
        KeyCode::Char(c) if c.is_ascii_uppercase() => {
            mods |= KeyModifiers::SHIFT;
            KeyCode::Char(c.to_ascii_lowercase())
        }
        KeyCode::Char(c) if c.is_uppercase() => {
            KeyCode::Char(c.to_lowercase().next().unwrap_or(c))
        }
        KeyCode::BackTab => KeyCode::BackTab,
        c => c,
    };
    // symbols typed with shift should match plain bindings
    if let KeyCode::Char(c) = code {
        if !c.is_ascii_alphabetic() && !c.is_ascii_digit() && mods == KeyModifiers::SHIFT {
            mods = KeyModifiers::NONE;
        }
    }
    Input::Key(code, mods)
}

pub fn input_from_mouse(ev: &MouseEvent) -> Option<Input> {
    let k = match ev.kind {
        MouseEventKind::ScrollUp => MouseKind::ScrollUp,
        MouseEventKind::ScrollDown => MouseKind::ScrollDown,
        MouseEventKind::ScrollLeft => MouseKind::ScrollLeft,
        MouseEventKind::ScrollRight => MouseKind::ScrollRight,
        MouseEventKind::Down(MouseButton::Left) => MouseKind::ButtonDownLeft,
        MouseEventKind::Down(MouseButton::Right) => MouseKind::ButtonDownRight,
        MouseEventKind::Up(MouseButton::Left) => MouseKind::ButtonUpLeft,
        MouseEventKind::Up(MouseButton::Right) => MouseKind::ButtonUpRight,
        _ => return None,
    };
    Some(Input::Mouse(k))
}

pub type Keymap = HashMap<Input, Action>;

pub fn default_keymap() -> Vec<(&'static str, Action)> {
    vec![
        ("up", Action::Up),
        ("down", Action::Down),
        ("alt-right", Action::ScrollRight),
        ("shift-alt-right", Action::ScrollHorizontalEnd),
        ("alt-left", Action::ScrollLeft),
        ("shift-alt-left", Action::ScrollHorizontalHome),
        ("pageup", Action::PageUp),
        ("pagedown", Action::PageDown),
        ("home", Action::MoveTop),
        ("end", Action::MoveEnd),
        ("tab", Action::ToggleForcus),
        ("left", Action::ForcusWatchPane),
        ("right", Action::ForcusHistoryPane),
        ("q", Action::Quit),
        ("esc", Action::Reset),
        ("ctrl-c", Action::Cancel),
        ("h", Action::Help),
        ("c", Action::ToggleColor),
        ("n", Action::ToggleLineNumber),
        ("r", Action::ToggleReverse),
        ("m", Action::ToggleMouseSupport),
        ("t", Action::ToggleViewPaneUI),
        ("backspace", Action::ToggleViewHistoryPane),
        ("b", Action::ToggleBorderWithScrollBar),
        ("d", Action::ToggleDiffMode),
        ("0", Action::SetDiffModePlane),
        ("1", Action::SetDiffModeWatch),
        ("2", Action::SetDiffModeLine),
        ("3", Action::SetDiffModeWord),
        ("shift-o", Action::SetDiffOnly),
        ("o", Action::ToggleOutputMode),
        ("f3", Action::SetOutputModeOutput),
        ("f1", Action::SetOutputModeStdout),
        ("f2", Action::SetOutputModeStderr),
        ("w", Action::ToggleWrapMode),
        ("ctrl-n", Action::NextKeyword),
        ("ctrl-p", Action::PrevKeyword),
        ("shift-s", Action::ToggleHistorySummary),
        ("+", Action::IntervalPlus),
        ("-", Action::IntervalMinus),
        ("p", Action::TogglePause),
        ("/", Action::ChangeFilterMode),
        ("*", Action::ChangeRegexFilterMode),
        ("mouse-scroll_up", Action::MouseScrollUp),
        ("mouse-scroll_down", Action::MouseScrollDown),
        ("mouse-button_down_left", Action::MouseButtonLeft),
    ]
}

fn default_input(name: &str) -> Input {
    if name == "-" {
        return Input::Key(KeyCode::Char('-'), KeyModifiers::NONE);
    }
    parse_input(name).unwrap()
}

/// Build the keymap; returns the map and the insertion order of keys.
pub fn build_keymap(custom: &[String]) -> Result<(Keymap, Vec<Input>), ()> {
    let mut map: Keymap = HashMap::new();
    let mut order: Vec<Input> = Vec::new();
    for (k, a) in default_keymap() {
        let i = default_input(k);
        if !map.contains_key(&i) {
            order.push(i);
        }
        map.insert(i, a);
    }
    for c in custom {
        let parts: Vec<&str> = c.split('=').collect();
        if parts.len() != 2 {
            return Err(());
        }
        let key = parts[0].trim();
        let act = parts[1].trim();
        let input = parse_input(key).ok_or(())?;
        let action = action_from_name(act).ok_or(())?;
        if !map.contains_key(&input) {
            order.push(input);
        }
        map.insert(input, action);
    }
    Ok((map, order))
}
