// Conversion of ANSI escape sequences into ratatui styles.
use ratatui::style::{Color, Modifier, Style};
use termwiz::cell::{Blink, Intensity, Underline};
use termwiz::color::ColorSpec;
use termwiz::escape::csi::{Sgr, CSI};
use termwiz::escape::parser::Parser;
use termwiz::escape::Action;

/// Parse a single line of text containing escape sequences into styled segments.
pub fn parse_line(line: &str) -> Vec<(String, Style)> {
    let mut parser = Parser::new();
    let mut segs: Vec<(String, Style)> = Vec::new();
    let mut cur = String::new();
    let mut style = Style::default();
    parser.parse(line.as_bytes(), |action| match action {
        Action::Print(c) => cur.push(c),
        Action::PrintString(s) => cur.push_str(&s),
        Action::CSI(CSI::Sgr(sgr)) => {
            if !cur.is_empty() {
                segs.push((std::mem::take(&mut cur), style));
            }
            style = apply_sgr(style, sgr);
        }
        _ => {}
    });
    if !cur.is_empty() {
        segs.push((cur, style));
    }
    segs
}

fn color_from_spec(spec: ColorSpec) -> Option<Color> {
    match spec {
        ColorSpec::Default => Some(Color::Reset),
        ColorSpec::PaletteIndex(i) => Some(Color::Indexed(i)),
        ColorSpec::TrueColor(c) => {
            let (r, g, b, _) = c.to_srgb_u8();
            Some(Color::Rgb(r, g, b))
        }
    }
}

fn apply_sgr(style: Style, sgr: Sgr) -> Style {
    match sgr {
        Sgr::Reset => Style::default(),
        Sgr::Intensity(i) => match i {
            Intensity::Bold => style.add_modifier(Modifier::BOLD),
            Intensity::Half => style.add_modifier(Modifier::DIM),
            Intensity::Normal => style.remove_modifier(Modifier::BOLD | Modifier::DIM),
        },
        Sgr::Underline(u) => match u {
            Underline::None => style.remove_modifier(Modifier::UNDERLINED),
            _ => style.add_modifier(Modifier::UNDERLINED),
        },
        Sgr::Blink(b) => match b {
            Blink::None => style.remove_modifier(Modifier::SLOW_BLINK | Modifier::RAPID_BLINK),
            Blink::Slow => style.add_modifier(Modifier::SLOW_BLINK),
            Blink::Rapid => style.add_modifier(Modifier::RAPID_BLINK),
        },
        Sgr::Italic(true) => style.add_modifier(Modifier::ITALIC),
        Sgr::Italic(false) => style.remove_modifier(Modifier::ITALIC),
        Sgr::Inverse(true) => style.add_modifier(Modifier::REVERSED),
        Sgr::Inverse(false) => style.remove_modifier(Modifier::REVERSED),
        Sgr::StrikeThrough(true) => style.add_modifier(Modifier::CROSSED_OUT),
        Sgr::StrikeThrough(false) => style.remove_modifier(Modifier::CROSSED_OUT),
        Sgr::Foreground(spec) => match spec {
            ColorSpec::TrueColor(_) => match color_from_spec(spec) {
                Some(c) => style.bg(c),
                None => style,
            },
            _ => match color_from_spec(spec) {
                Some(c) => style.fg(c),
                None => style,
            },
        },
        Sgr::Background(spec) => match color_from_spec(spec) {
            Some(c) => style.bg(c),
            None => style,
        },
        _ => style,
    }
}
