// Generation of watch pane content (logical lines made of styled segments).
use crate::ansi;
use crate::ansi_strip;
use crate::batch::watch_diff_line_ansi;
use crate::common::DiffMode;
use crate::diff::{ChangeTag, TextDiff};
use ratatui::style::{Color, Modifier, Style};

pub type Seg = (String, Style);

#[derive(Clone, Debug, Default)]
pub struct WLine {
    /// prefix segments (line number, diff marks) - not searchable
    pub prefix: Vec<Seg>,
    /// content segments - searchable
    pub content: Vec<Seg>,
}

pub struct ViewOptions {
    pub color: bool,
    pub line_number: bool,
    pub diff_mode: DiffMode,
    pub diff_only: bool,
    pub tab_size: u16,
}

const ZWSP: &str = "\u{200b}";

pub fn expand_tabs(text: &str, tab_size: u16) -> String {
    if !text.contains('\t') {
        return text.to_string();
    }
    let ts = tab_size as usize;
    let mut out = String::with_capacity(text.len());
    let mut col = 0usize;
    for c in text.chars() {
        if c == '\n' {
            out.push(c);
            col = 0;
        } else if c == '\t' {
            if ts == 0 {
                continue;
            }
            let n = ts - (col % ts);
            for _ in 0..n {
                out.push(' ');
            }
            col += n;
        } else {
            out.push(c);
            col += 1;
        }
    }
    out
}

fn escape_text(s: &str) -> String {
    s.replace('\x1b', "\\x1b")
}

fn plain_content(line: &str, color: bool) -> Vec<Seg> {
    if color {
        ansi::parse_line(line)
    } else {
        vec![(escape_text(line), Style::default())]
    }
}

fn number_width(n: usize) -> usize {
    n.to_string().len()
}

fn number_seg(n: usize, width: usize, color: Color) -> Seg {
    (
        format!("{:>width$} | ", n, width = width),
        Style::default().fg(color),
    )
}

pub const NUM_EQ: Color = Color::DarkGray;
pub const NUM_DEL: Color = Color::Rgb(118, 0, 0);
pub const NUM_INS: Color = Color::Rgb(56, 119, 120);

pub fn generate(old: Option<&str>, new: &str, opt: &ViewOptions) -> Vec<WLine> {
    let new_t = expand_tabs(new, opt.tab_size);
    let old_t = old.map(|o| expand_tabs(o, opt.tab_size));
    match (opt.diff_mode, old_t.as_deref()) {
        (DiffMode::Plane, _) | (_, None) => {
            if let (DiffMode::Line | DiffMode::Word, None) = (opt.diff_mode, old_t.as_deref()) {
                return gen_line_first(&new_t, opt);
            }
            gen_plane(&new_t, opt)
        }
        (DiffMode::Watch, Some(o)) => {
            if opt.color {
                gen_watch_color(o, &new_t, opt)
            } else {
                gen_watch(o, &new_t, opt)
            }
        }
        (DiffMode::Line, Some(o)) => gen_line(o, &new_t, opt, false),
        (DiffMode::Word, Some(o)) => gen_line(o, &new_t, opt, true),
    }
}

fn gen_plane(new: &str, opt: &ViewOptions) -> Vec<WLine> {
    let lines: Vec<&str> = new.lines().collect();
    let width = number_width(lines.len());
    lines
        .iter()
        .enumerate()
        .map(|(i, l)| {
            let mut w = WLine::default();
            if opt.line_number {
                w.prefix.push(number_seg(i + 1, width, NUM_EQ));
            }
            w.content = plain_content(l, opt.color);
            w
        })
        .collect()
}

fn gen_line_first(new: &str, opt: &ViewOptions) -> Vec<WLine> {
    let lines: Vec<&str> = new.lines().collect();
    let width = number_width(lines.len());
    let mut rv = Vec::new();
    for (i, l) in lines.iter().enumerate() {
        if opt.diff_only {
            continue;
        }
        let mut w = WLine::default();
        if opt.line_number {
            w.prefix.push(number_seg(i + 1, width, NUM_EQ));
        }
        w.prefix.push(("   ".to_string(), Style::default()));
        w.content = plain_content(l, opt.color);
        rv.push(w);
    }
    rv
}

