// Row layout (wrapping) and rendering of the watch pane.
use crate::view::{Seg, WLine};
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::{Color, Style};
use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

#[derive(Clone, Debug)]
pub struct Cell {
    pub sym: String,
    pub style: Style,
    pub width: usize,
}

pub type Row = Vec<Cell>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Match {
    pub line: usize,
    pub start: usize,
    pub end: usize,
}

fn graphemes_of(segs: &[Seg]) -> Vec<Cell> {
    let mut v = Vec::new();
    for (text, style) in segs {
        for g in text.graphemes(true) {
            v.push(Cell {
                sym: g.to_string(),
                style: *style,
                width: g.width(),
            });
        }
    }
    v
}

/// Apply keyword highlighting to the content segments of a line.
pub fn highlight(content: &[Seg], matches: &[(usize, usize, bool)]) -> Vec<Seg> {
    if matches.is_empty() {
        return content.to_vec();
    }
    let text: String = content.iter().map(|(s, _)| s.as_str()).collect();
    // chunk boundaries (exclusive end offsets of chunks)
    let mut chunk_ends: Vec<usize> = Vec::new();
    {
        let mut off = 0;
        for part in text.split_inclusive(' ') {
            off += part.len();
            chunk_ends.push(off);
        }
    }
    let chunk_of = |pos: usize| -> usize {
        chunk_ends
            .iter()
            .position(|&e| pos < e)
            .unwrap_or(chunk_ends.len())
    };
    // collect boundaries
    let mut bounds: Vec<usize> = vec![0, text.len()];
    let mut off = 0;
    for (s, _) in content {
        off += s.len();
        bounds.push(off);
    }
    for &e in &chunk_ends {
        bounds.push(e);
    }
    for &(s, e, _) in matches {
        bounds.push(s);
        bounds.push(e);
    }
    bounds.sort_unstable();
    bounds.dedup();
    let seg_style_at = |pos: usize| -> Style {
        let mut o = 0;
        for (s, st) in content {
            if pos < o + s.len() {
                return *st;
            }
            o += s.len();
        }
        Style::default()
    };
    let mut out: Vec<Seg> = Vec::new();
    for w in bounds.windows(2) {
        let (a, b) = (w[0], w[1]);
        if a >= b {
            continue;
        }
        if !text.is_char_boundary(a) || !text.is_char_boundary(b) {
            continue;
        }
        let piece = &text[a..b];
        let mut st = seg_style_at(a);
        for &(ms, me, focused) in matches {
            if a >= ms && b <= me {
                let first_chunk = chunk_of(ms) == chunk_of(a);
                let bg = if focused && first_chunk {
                    Color::Yellow
                } else {
                    Color::Cyan
                };
                st = st.fg(Color::Black).bg(bg);
                break;
            }
        }
        match out.last_mut() {
            Some(last) if last.1 == st => last.0.push_str(piece),
            _ => out.push((piece.to_string(), st)),
        }
    }
    out
}

/// Lay out a logical line into rows.
pub fn layout_line(line: &WLine, content: &[Seg], width: usize, wrap: bool) -> Vec<Row> {
    let mut all: Vec<Seg> = line.prefix.clone();
    all.extend_from_slice(content);
    let cells = graphemes_of(&all);
    if !wrap {
        return vec![cells];
    }
    if width == 0 {
        return vec![Vec::new()];
    }
    // build chunks split after each space
    let mut chunks: Vec<Vec<Cell>> = Vec::new();
    let mut cur: Vec<Cell> = Vec::new();
    for c in cells {
        let is_space = c.sym == " ";
        cur.push(c);
        if is_space {
            chunks.push(std::mem::take(&mut cur));
        }
    }
    if !cur.is_empty() {
        chunks.push(cur);
    }
    let mut rows: Vec<Row> = Vec::new();
    let mut row: Row = Vec::new();
    let mut row_w = 0usize;
    for chunk in chunks {
        let cw: usize = chunk.iter().map(|c| c.width).sum();
        if row_w + cw <= width {
            row_w += cw;
            row.extend(chunk);
            continue;
        }
        if row_w > 0 {
            rows.push(std::mem::take(&mut row));
            row_w = 0;
        }
        if cw <= width {
            row_w = cw;
            row.extend(chunk);
            continue;
        }
        for c in chunk {
            if row_w + c.width > width && row_w > 0 {
                rows.push(std::mem::take(&mut row));
                row_w = 0;
            }
            row_w += c.width;
            row.push(c);
        }
    }
    rows.push(row);
    rows
}

pub fn row_width(row: &Row) -> usize {
    row.iter().map(|c| c.width).sum()
}

/// Render rows into the buffer area with vertical / horizontal offsets.
pub fn render_rows(rows: &[Row], area: Rect, buf: &mut Buffer, scroll: usize, hscroll: usize) {
    let maxw = area.width as usize;
    for (i, row) in rows.iter().skip(scroll).take(area.height as usize).enumerate() {
        let y = area.y + i as u16;
        let mut x = 0usize;
        let mut hoff = hscroll;
        for c in row {
            if c.width > maxw {
                continue;
            }
            if x + c.width > maxw {
                break;
            }
            if hoff > 0 {
                if c.width > hoff {
                    hoff = 0;
                } else {
                    hoff -= c.width;
                    continue;
                }
            }
            if c.width == 0 {
                continue;
            }
            let cell = &mut buf[(area.x + x as u16, y)];
            cell.set_symbol(&c.sym);
            cell.set_style(c.style);
            x += c.width;
        }
    }
}
