}

/// Render rows into the buffer area with vertical / horizontal offsets.
pub fn render_rows(rows: &[Row], area: Rect, buf: &mut Buffer, scroll: usize, hscroll: usize) {
    let maxw = area.width as usize;
    for (i, row) in rows.iter().skip(scroll).take(area.height as usize).enumerate() {
        let y = area.y + i as u16;
        let mut x = 0usize;
        let mut hoff = hscroll;
        for c in row {
            if c.width > maxw {
                continue;
            }
            if x + c.width > maxw {
                break;
            }
            if hoff > 0 {
                if c.width > hoff {
                    hoff = 0;
                } else {
                    hoff -= c.width;
                    continue;
                }
            }
            if c.width == 0 {
                continue;
            }
            let cell = &mut buf[(area.x + x as u16, y)];
            cell.set_symbol(&c.sym);
            cell.set_style(c.style);
            x += c.width;
        }
    }
}
