    }

    fn reset_filter(&mut self) {
        self.filtered = false;
        self.filter_keyword.clear();
        self.input_text.clear();
        self.filter_prefix = " ".to_string();
        self.focus_match = 0;
        self.selected = 0;
    }

    fn start_input(&mut self, kind: InputKind) {
        self.input = Some(kind);
        self.update_prefix();
    }

    fn input_char(&self) -> &'static str {
        match self.input {
            Some(InputKind::Regex) => "*",
            _ => "/",
        }
    }

    fn update_prefix(&mut self) {
        if self.input.is_some() {
            if self.filtered && !self.input_text.is_empty() {
                self.filter_prefix = " ".to_string();
            } else {
                self.filter_prefix = self.input_char().to_string();
            }
        }
    }

    fn submit_input(&mut self) {
        let kind = match self.input {
            Some(k) => k,
            None => return,
        };
        if self.input_text.is_empty() {
            self.filtered = false;
            self.filter_keyword.clear();
            self.focus_match = 0;
            self.update_prefix();
            return;
        }
        if kind == InputKind::Regex && regex::Regex::new(&self.input_text).is_err() {
            return;
        }
        self.filtered = true;
        self.filter_regex = kind == InputKind::Regex;
        self.filter_keyword = self.input_text.clone();
        self.filter_prefix = self.input_char().to_string();
        self.input = None;
        self.focus_match = 0;
        self.selected = 0;
        self.pending_focus_scroll = true;
    }

    fn move_keyword(&mut self, next: bool) {
        let width = self.watch_area.width as usize;
        let (_, _, matches) = self.build_rows(width);
        if matches.is_empty() {
            return;
        }
        let n = matches.len();
        if next {
            self.focus_match = (self.focus_match + 1) % n;
        } else {
            self.focus_match = (self.focus_match + n - 1) % n;
        }
        self.pending_focus_scroll = true;
    }

    fn scroll_to_focus(&mut self) {
        let width = self.watch_area.width as usize;
        let (rows, starts, matches) = self.build_rows(width);
        let _ = rows;
        if let Some(m) = matches.get(self.focus_match) {
            let row = starts[m.line];
            let h = self.watch_inner_height();
            if row < self.watch_scroll {
                self.watch_scroll = row;
            } else if h > 0 && row >= self.watch_scroll + h {
                self.watch_scroll = row + 1 - h;
            }
        }
    }

    fn handle_key(&mut self, ev: crossterm::event::KeyEvent) {
        if ev.kind != KeyEventKind::Press {
            return;
        }
        if self.exit_dialog {
            match ev.code {
                KeyCode::Char('y') | KeyCode::Char('Y') | KeyCode::Char('q') | KeyCode::Char('Q') => {
                    self.quit = true
                }
                KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => self.exit_dialog = false,
                KeyCode::Char('c') if ev.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.quit = true
                }
                _ => {}
            }
            return;
        }
        if self.input.is_some() {
            match ev.code {
                KeyCode::Enter => self.submit_input(),
                KeyCode::Backspace => {
                    self.input_text.pop();
                    self.update_prefix();
                }
                KeyCode::Char('c') if ev.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.exit_dialog = true;
                }
                KeyCode::Char(c) => {
                    if !ev.modifiers.contains(KeyModifiers::CONTROL)
                        && !ev.modifiers.contains(KeyModifiers::ALT)
                    {
                        self.input_text.push(c);
                        self.update_prefix();
                    }
                }
                _ => {}
            }
            return;
        }
        let input = keymap::input_from_key(&ev);
        let action = self.cfg.keymap.get(&input).cloned();
        if self.help {
            match action {
                Some(Action::Up) | Some(Action::WatchPaneUp) | Some(Action::HistoryPaneUp) => {
                    self.help_scroll = self.help_scroll.saturating_sub(1)
                }
                Some(Action::Down) | Some(Action::WatchPaneDown) | Some(Action::HistoryPaneDown) => {
                    if self.help_scroll < self.help_max_scroll() {
                        self.help_scroll += 1
                    }
                }
                Some(Action::PageUp) => {
                    let p = self.help_page();
                    self.help_scroll = self.help_scroll.saturating_sub(p)
                }
                Some(Action::PageDown) => {
                    let p = self.help_page();
                    self.help_scroll = (self.help_scroll + p).min(self.help_max_scroll())
                }
                Some(Action::MoveTop) => self.help_scroll = 0,
                Some(Action::MoveEnd) => self.help_scroll = self.help_max_scroll(),
                Some(Action::Help) | Some(Action::Reset) => self.help = false,
                Some(Action::Quit) | Some(Action::Cancel) => self.exit_dialog = true,
                Some(Action::ForceCancel) => self.quit = true,
                _ => {}
            }
            return;
        }
        if let Some(a) = action {
            self.action(a);
        }
    }

    fn handle_mouse(&mut self, ev: MouseEvent) {
        if !self.cfg.mouse {
            return;
        }
        let input = match keymap::input_from_mouse(&ev) {
            Some(i) => i,
            None => return,
        };
        let action = match self.cfg.keymap.get(&input) {
            Some(a) => *a,
            None => return,
        };
        if self.help || self.exit_dialog {
            return;
        }
        let in_history = self.show_history
            && ev.column >= self.history_area.x
            && ev.column < self.history_area.x + self.history_area.width
            && ev.row >= self.history_area.y
            && ev.row < self.history_area.y + self.history_area.height;
        match action {
            Action::MouseScrollUp => {
                if in_history {
                    self.set_selected(self.selected.saturating_sub(1));
                } else {
                    self.watch_scroll_up(2);
                }
            }
            Action::MouseScrollDown => {
                if in_history {
                    self.set_selected(self.selected + 1);
                } else {
                    self.watch_scroll_down(2);
                }
            }
            Action::MouseButtonLeft => {
                if in_history {
                    let row = (ev.row - self.history_area.y) as usize;
                    let offset = self.table_state.offset();
                    let per = self.history_row_height();
                    let idx = if per <= 1 {
                        offset + row
                    } else if row == 0 {
                        offset
                    } else {
                        offset + 1 + (row - 1) / per
                    };
                    if idx < self.history_len() {
                        self.selected = idx;
                    }
                }
            }
            a => self.action(a),
        }
    }

    fn history_row_height(&self) -> usize {
        if self.summary {
            if self.cfg.summary_char {
                3
            } else {
                2
            }
        } else {
            1
        }
    }

    // ---------------------------------------------------------------
    // help
    fn help_lines(&self) -> Vec<Line<'static>> {
        let green = Style::default().fg(Color::LightGreen);
        let mut items: Vec<(Action, Input)> = Vec::new();
        for i in &self.cfg.keymap_order {
            if let Some(a) = self.cfg.keymap.get(i) {
                items.push((*a, *i));
            }
        }
        items.sort_by_key(|(a, _)| *a);
        let mut v = Vec::new();
        for (a, i) in items {
            v.push(Line::from(vec![
                Span::styled(" - [", green),
                Span::styled(i.display(), Style::default().fg(Color::Yellow)),
                Span::styled("] key :", green),
            ]));
            v.push(Line::from(vec![
                Span::styled("         ", green),
                Span::styled(
                    keymap::action_description(a).to_string(),
                    Style::default().fg(Color::White),
                ),
            ]));
        }
        v
    }

    fn help_area(&self, area: Rect) -> Rect {
        centered_rect(80, 70, area)
    }

    fn help_inner_height(&self) -> usize {
        let (w, h) = crossterm::terminal::size().unwrap_or((80, 24));
        let a = self.help_area(Rect::new(0, 0, w, h));
        a.height.saturating_sub(2) as usize
    }

    fn help_page(&self) -> usize {
        self.help_inner_height()
    }

    fn help_max_scroll(&self) -> usize {
        let n = self.help_lines().len();
        let h = self.help_inner_height();
        (n + 2).saturating_sub(h)
    }

    // ---------------------------------------------------------------
    fn draw(&mut self, f: &mut Frame) {
        let area = f.area();
        let header_h: u16 = if self.show_header { 2 } else { 0 };
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(header_h), Constraint::Min(0)])
            .split(area);
        let header_area = chunks[0];
        let body = chunks[1];
        let (watch_outer, hist_outer) = if self.show_history {
            let c = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Min(0), Constraint::Length(25)])
                .split(body);
            (c[0], Some(c[1]))
        } else {
            (body, None)
        };
        if self.show_header {
            self.draw_header(f, header_area);
        }
        // watch pane block
        let border = self.cfg.border;
        let mut watch_inner = watch_outer;
        if border {
            let mut borders = Borders::RIGHT;
            if self.show_header {
                borders |= Borders::TOP;
            }
            let set = symbols::border::Set {
                top_right: symbols::line::HORIZONTAL_DOWN,
                ..symbols::border::PLAIN
            };
            let block = Block::default()
                .borders(borders)
                .border_set(set)
                .border_style(Style::default().fg(Color::DarkGray));
            watch_inner = block.inner(watch_outer);
            f.render_widget(block, watch_outer);
        }
        self.watch_area = watch_inner;
        if let Some(h) = hist_outer {
            let mut inner = h;
            if border && self.show_header {
                let block = Block::default()
                    .borders(Borders::TOP)
                    .border_style(Style::default().fg(Color::DarkGray));
                inner = block.inner(h);
                f.render_widget(block, h);
            }
            self.history_area = inner;
        } else {
            self.history_area = Rect::default();
        }
        if self.pending_focus_scroll {
            self.pending_focus_scroll = false;
            self.scroll_to_focus();
        }
        self.draw_watch(f, watch_inner);
        if border && self.cfg.scrollbar {
            self.draw_scrollbar(f, watch_outer);
        }
        if hist_outer.is_some() {
            let ha = self.history_area;
            self.draw_history(f, ha);
        }
        if self.help {
            self.draw_help(f, area);
        }
        if self.exit_dialog {
            self.draw_exit(f, area);
        }
    }

    fn draw_header(&self, f: &mut Frame, area: Rect) {
        let w = area.width as usize;
        let paused = self.ctl.paused.load(Ordering::SeqCst);
        let interval = *self.ctl.interval.lock().unwrap();
        let interval_s = if paused {
            format!("{:>9}", "Paused")
        } else {
            format!("{:>9.3}", interval)
        };
        let banner = if self.cfg.help_banner {
            "Display help with h key!"
        } else {
            ""
        };
        let fixed = 16 + 1 + banner.chars().count() + 1 + 23;
        let cmd_w = w.saturating_sub(1).saturating_sub(fixed);
        let cmd = format!("{:<width$}", self.cfg.command, width = cmd_w);
        let (ts, status) = match &self.latest {
            Some(r) => (r.timestamp.clone(), r.status),
            None => (String::new(), true),
        };
        let cmd_color = if status { Color::Green } else { Color::Red };
        let line1 = Line::from(vec![
            Span::raw("Every "),
            Span::styled(interval_s, Style::default().fg(Color::Cyan)),
            Span::raw(":"),
            Span::styled(cmd, Style::default().fg(cmd_color)),
            Span::raw(" "),
            Span::styled(banner, Style::default().add_modifier(Modifier::REVERSED)),
            Span::raw(" "),
            Span::styled(ts, Style::default().fg(Color::Cyan)),
        ]);
        let left_w = w.saturating_sub(1).saturating_sub(58);
        let mut spans: Vec<Span> = Vec::new();
        if self.filter_prefix.is_empty() {
            spans.push(Span::styled(
                " ".repeat(left_w),
                Style::default().fg(Color::Gray),
            ));
        } else {
            let kw = if self.input.is_some() {
                self.input_text.clone()
            } else {
                self.filter_keyword.clone()
            };
            spans.push(Span::styled(
                self.filter_prefix.clone(),
                Style::default().fg(Color::Gray),
            ));
            spans.push(Span::styled(
                format!("{:<width$}", kw, width = left_w),
                Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
            ));
        }
        let on = Style::default()
            .fg(Color::Green)
            .add_modifier(Modifier::BOLD | Modifier::REVERSED);
        let flag = |name: &'static str, v: bool| -> Span<'static> {
            if v {
                Span::styled(name, on)
            } else {
                Span::raw(name)
            }
        };
        spans.push(Span::raw("["));
        spans.push(flag("Number", self.cfg.line_number));
        spans.push(Span::raw("] ["));
        spans.push(flag("Color", self.cfg.color));
        spans.push(Span::raw("] ["));
        spans.push(flag("Reverse", self.cfg.reverse));
        spans.push(Span::raw("] ["));
        let om = match self.cfg.output_mode {
            OutputMode::Output => "Output",
            OutputMode::Stdout => "Stdout",
            OutputMode::Stderr => "Stderr",
        };
        spans.push(Span::styled(
            om,
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::REVERSED),
        ));
        spans.push(Span::raw("] ["));
        let fo = match self.focus {
            Focus::History => "History",
            Focus::Watch => "Watch  ",
        };
        spans.push(Span::styled(
            fo,
            Style::default().fg(Color::Cyan).add_modifier(Modifier::REVERSED),
        ));
        spans.push(Span::raw("] ["));
        let dm = match (self.cfg.diff_mode, self.cfg.diff_only) {
            (DiffMode::Plane, _) => "None      ",
            (DiffMode::Watch, _) => "Watch     ",
            (DiffMode::Line, false) => "Line      ",
            (DiffMode::Line, true) => "Line(Only)",
            (DiffMode::Word, false) => "Word      ",
            (DiffMode::Word, true) => "Word(Only)",
        };
        spans.push(Span::styled(
            dm,
            Style::default()
                .fg(Color::Magenta)
                .add_modifier(Modifier::REVERSED),
        ));
        spans.push(Span::raw("]"));
        let line2 = Line::from(spans);
        f.render_widget(Paragraph::new(Text::from(vec![line1, line2])), area);
    }

    fn draw_watch(&mut self, f: &mut Frame, area: Rect) {
        let (rows, _, _) = self.build_rows(area.width as usize);
        let hs = if self.wrap { 0 } else { self.watch_hscroll };
        render::render_rows(&rows, area, f.buffer_mut(), self.watch_scroll, hs);
    }

    fn draw_scrollbar(&self, f: &mut Frame, outer: Rect) {
        let (rows, _, _) = self.build_rows(self.watch_area.width as usize);
        let h = self.watch_area.height as usize;
        let len = rows.len().saturating_sub(h);
        let mut state = ScrollbarState::new(len).position(self.watch_scroll);
        let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight)
            .begin_symbol(None)
            .end_symbol(None)
            .track_symbol(Some(symbols::line::VERTICAL))
            .style(Style::default().fg(Color::DarkGray));
        let area = Rect {
            x: outer.x,
            y: self.watch_area.y,
            width: outer.width,
            height: self.watch_area.height,
        };
        f.render_stateful_widget(sb, area, &mut state);
    }

    fn draw_history(&mut self, f: &mut Frame, area: Rect) {
        let vis = self.visible_history();
        let mut rows: Vec<TRow> = Vec::new();
        rows.push(TRow::new(vec![TCell::from(Span::styled(
            "latest",
            Style::default().fg(Color::Blue),
        ))]));
        let summary = self.summary;
        let schar = self.cfg.summary_char;
        for &i in &vis {
            let r = &self.entries[i].result;
            let color = if r.status { Color::Green } else { Color::Red };
            let ts = r.timestamp.clone();
            if summary {
                let s = self.summary_for(i);
                let mut lines = vec![Line::from(Span::styled(ts, Style::default().fg(color)))];
                lines.push(Line::from(vec![
                    Span::raw("Line: "),
                    Span::styled(
                        format!("+{:>7}", s.line_add),
                        Style::default().fg(Color::Green),
                    ),
                    Span::raw(" "),
                    Span::styled(
                        format!("-{:>7}", s.line_rem),
                        Style::default().fg(Color::Red),
                    ),
                ]));
                if schar {
                    lines.push(Line::from(vec![
                        Span::raw("Char: "),
                        Span::styled(
                            format!("+{:>7}", s.char_add),
                            Style::default().fg(Color::Green),
                        ),
                        Span::raw(" "),
                        Span::styled(
                            format!("-{:>7}", s.char_rem),
                            Style::default().fg(Color::Red),
                        ),
                    ]));
                }
                let n = lines.len() as u16;
                rows.push(TRow::new(vec![TCell::from(Text::from(lines))]).height(n));
            } else {
                rows.push(TRow::new(vec![TCell::from(Span::styled(
                    ts,
                    Style::default().fg(color),
                ))]));
            }
        }
        let hl = match self.focus {
            Focus::Watch => Style::default()
                .fg(Color::Gray)
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
            Focus::History => {
                if self.selected == 0 {
                    Style::default()
                        .fg(Color::Gray)
                        .bg(Color::Blue)
                        .add_modifier(Modifier::BOLD)
                } else {
                    Style::default()
                        .bg(Color::DarkGray)
                        .add_modifier(Modifier::BOLD)
                }
            }
        };
        if self.selected > vis.len() {
            self.selected = vis.len();
        }
        let table = Table::new(rows, [Constraint::Percentage(100)])
            .row_highlight_style(hl)
            .highlight_symbol(">>")
            .highlight_spacing(ratatui::widgets::HighlightSpacing::Always)
            .column_spacing(0);
        self.table_state.select(Some(self.selected));
        f.render_stateful_widget(table, area, &mut self.table_state);
    }

    fn draw_help(&mut self, f: &mut Frame, area: Rect) {
        let r = self.help_area(area);
        let lines = self.help_lines();
        f.render_widget(Clear, r);
        let block = Block::default()
            .title(" [help] ")
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::Gray));
        let p = Paragraph::new(Text::from(lines))
            .style(Style::default().fg(Color::LightGreen))
            .block(block)
            .scroll((self.help_scroll as u16, 0));
        f.render_widget(p, r);
    }

    fn draw_exit(&self, f: &mut Frame, area: Rect) {
        let w: u16 = 32;
        let h: u16 = 5;
        let x = area.x + area.width.saturating_sub(w) / 2;
        let y = area.y + area.height.saturating_sub(h) / 2;
        let r = Rect::new(x, y, w.min(area.width), h.min(area.height));
        f.render_widget(Clear, r);
        let block = Block::default()
            .title(" [exit] ")
            .borders(Borders::ALL)
            .border_type(BorderType::Double)
            .border_style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD));
        let text = Text::from(vec![
            Line::from(" Exit hwatch?"),
            Line::from("   Press 'Y' or 'Q'  : Quit."),
            Line::from("   Press 'N' or 'Esc': Stay."),
        ]);
        let p = Paragraph::new(text)
            .style(Style::default().add_modifier(Modifier::BOLD))
            .block(block);
        f.render_widget(p, r);
    }

    // ---------------------------------------------------------------
    pub fn load_history(&mut self, results: Vec<CommandResult>) {
        for r in results {
            if r.timestamp.is_empty() {
                continue;
            }
            self.push_result(r, true);
        }
    }

    fn on_result(&mut self, r: CommandResult) {
        let before = self
            .entries
            .last()
            .map(|e| e.result.clone())
            .unwrap_or_else(CommandResult::empty);
        let changed = self.push_result(r.clone(), false);
        if changed {
            if let Some(l) = self.logger.as_mut() {
                l.write(&r);
            }
            if self.cfg.beep {
                use std::io::Write;
                let mut o = std::io::stdout();
                let _ = o.write_all(b"\x07");
                let _ = o.flush();
            }
            if let Some(ac) = &self.cfg.after_command {
                exec::exec_after_command(ac, &before, &r);
            }
        }
    }

    pub fn run(&mut self, rx: Receiver<CommandResult>) -> std::io::Result<()> {
        let mut terminal = setup_terminal(self.cfg.mouse)?;
        let res = self.event_loop(&mut terminal, rx);
        restore_terminal(&mut terminal);
        res
    }

    fn event_loop(
        &mut self,
        terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
        rx: Receiver<CommandResult>,
    ) -> std::io::Result<()> {
        let mut dirty = true;
        loop {
            while let Ok(r) = rx.try_recv() {
                self.on_result(r);
                dirty = true;
            }
            if dirty {
                terminal.draw(|f| self.draw(f))?;
                dirty = false;
            }
            if self.quit {
                return Ok(());
            }
            if event::poll(Duration::from_millis(30))? {
                match event::read()? {
                    Event::Key(k) => {
                        self.handle_key(k);
                        dirty = true;
                    }
                    Event::Mouse(m) => {
                        self.handle_mouse(m);
                        dirty = true;
                    }
                    Event::Resize(_, _) => dirty = true,
                    _ => {}
                }
            }
            if self.quit {
                return Ok(());
            }
        }
    }
}

pub fn centered_rect(px: u16, py: u16, r: Rect) -> Rect {
    let v = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - py) / 2),
            Constraint::Percentage(py),
            Constraint::Percentage((100 - py) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - px) / 2),
            Constraint::Percentage(px),
            Constraint::Percentage((100 - px) / 2),
        ])
        .split(v[1])[1]
}

fn set_mouse(on: bool) {
    use crossterm::execute;
    let mut out = std::io::stdout();
    if on {
        let _ = execute!(out, crossterm::event::EnableMouseCapture);
    } else {
        let _ = execute!(out, crossterm::event::DisableMouseCapture);
    }
}

fn setup_terminal(mouse: bool) -> std::io::Result<Terminal<CrosstermBackend<std::io::Stdout>>> {
    use crossterm::execute;
    use crossterm::terminal::{enable_raw_mode, EnterAlternateScreen};
    enable_raw_mode()?;
    let mut out = std::io::stdout();
    execute!(out, EnterAlternateScreen)?;
    if mouse {
        execute!(out, crossterm::event::EnableMouseCapture)?;
    }
    let backend = CrosstermBackend::new(out);
    let mut t = Terminal::new(backend)?;
    t.hide_cursor()?;
    t.clear()?;
    Ok(t)
}

fn restore_terminal(t: &mut Terminal<CrosstermBackend<std::io::Stdout>>) {
    use crossterm::execute;
    use crossterm::terminal::{disable_raw_mode, LeaveAlternateScreen};
    let _ = disable_raw_mode();
    let _ = execute!(
        t.backend_mut(),
        LeaveAlternateScreen,
        crossterm::event::DisableMouseCapture
    );
    let _ = t.show_cursor();
}
