/// Row window computation (mirrors table scrolling behaviour).
fn row_bounds(heights: &[u16], selected: usize, offset: usize, max_height: u16) -> (usize, usize) {
    if heights.is_empty() {
        return (0, 0);
    }
    let offset = offset.min(heights.len().saturating_sub(1));
    let mut start = offset;
    let mut end = offset;
    let mut height: u16 = 0;
    for h in heights.iter().skip(offset) {
        if height + *h > max_height {
            break;
        }
        height += *h;
        end += 1;
    }
    let selected = selected.min(heights.len() - 1);
    while selected >= end {
        height = height.saturating_add(heights[end]);
        end += 1;
        while height > max_height {
            height = height.saturating_sub(heights[start]);
            start += 1;
        }
    }
    while selected < start {
        start -= 1;
        height = height.saturating_add(heights[start]);
        while height > max_height {
            end -= 1;
            height = height.saturating_sub(heights[end]);
        }
    }
    (start, end)
}
