/// Watch diff where the padding is driven by (possibly weighted) lengths.
pub fn watch_diff_line_ansi_w(
    old_line: &str,
    new_line: &str,
    close: &str,
    old_len: usize,
    new_len_w: usize,
) -> String {
    if old_line == new_line {
        return new_line.to_string();
    }
    let oc: Vec<char> = old_line.chars().collect();
    let nc: Vec<char> = new_line.chars().collect();
    let max = old_len.max(new_len_w).max(nc.len());
    let mut s = String::new();
    let mut esc_mode = false;
    let mut esc = String::new();
    for x in 0..max {
        if x >= nc.len() {
            if x >= new_len_w && x < old_len {
                s.push_str("\\x1b[7m ");
                s.push_str(close);
            }
            continue;
        }
        let c = nc[x];
        if oc.get(x) == Some(&c) {
            s.push(c);
            continue;
        }
        if c == '\\x1b' {
            esc_mode = true;
            esc = "\\x1b".to_string();
            continue;
        }
        if esc_mode {
            esc.push(c);
            s.push_str(&esc);
            if c == 'm' {
                esc_mode = false;
            }
            continue;
        }
        s.push_str("\\x1b[7m");
        s.push(c);
        s.push_str(close);
    }
    s.push_str("\\x1b[0m");
    s
}

